sp_widget.css:
.wei-landing-wrapper {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #F8FAFC;
  min-height: 100vh;
  margin: 0;
  padding: 0;
  color: #1E293B;
}

/* Header */
.wei-top-header {
  background: #FFFFFF;
  border-bottom: 1px solid #E2E8F0;
  padding: 12px 24px;
}
.wei-header-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.wei-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}
.wei-brand-title {
  font-size: 16px;
  font-weight: 700;
  color: #1E293B;
}
.wei-header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}
.wei-nav-link {
  color: #475569;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
}
.wei-nav-link:hover { color: #1976D2; }
.btn-login-nav, .btn-logout-nav {
  background: #1976D2;
  color: #FFFFFF !important;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 6px;
  border: none;
  text-decoration: none !important;
}
.btn-login-nav:hover, .btn-logout-nav:hover {
  background: #1565C0;
}

/* Hero */
.wei-hero-banner {
  position: relative;
  background: linear-gradient(135deg, #0F172A 0%, #1E293B 50%, #172554 100%);
  background-size: cover;
  background-position: center;
  padding: 70px 20px 110px;
  text-align: center;
  color: #FFFFFF;
}
.wei-hero-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(30, 41, 59, 0.4) 0%, rgba(15, 23, 42, 0.85) 100%);
}
.wei-hero-inner {
  position: relative;
  z-index: 2;
  max-width: 800px;
  margin: 0 auto;
}
.wei-hero-heading {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.5px;
  margin: 0 0 10px;
  color: #FFFFFF;
}
.wei-hero-tagline {
  font-size: 16px;
  font-weight: 400;
  color: #E2E8F0;
  letter-spacing: 0.5px;
  margin: 0;
}

/* Main Container overlapping Hero */
.wei-main-container {
  max-width: 1100px;
  margin: -60px auto 40px;
  padding: 0 20px;
  position: relative;
  z-index: 3;
}

/* Logged-In Auth Card */
.wei-auth-session-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  padding: 20px 24px;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.wei-user-greeting {
  display: flex;
  align-items: center;
  gap: 14px;
}
.wei-avatar-circle {
  width: 44px;
  height: 44px;
  background: #1976D2;
  color: #FFFFFF;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 700;
}
.wei-user-meta h3 {
  margin: 0 0 3px;
  font-size: 17px;
  font-weight: 700;
  color: #0F172A;
}
.wei-user-meta p {
  margin: 0;
  font-size: 13px;
}
.wei-auth-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.btn-continue {
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 6px;
  color: #FFFFFF !important;
  text-decoration: none !important;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-staff { background: #1976D2; }
.btn-staff:hover { background: #1565C0; }
.btn-tech { background: #0284C7; }
.btn-tech:hover { background: #0369A1; }
.btn-sup { background: #4F46E5; }
.btn-sup:hover { background: #4338CA; }
.btn-switch-user {
  background: #F1F5F9;
  color: #475569 !important;
  border: 1px solid #CBD5E1;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 6px;
  text-decoration: none !important;
}
.btn-switch-user:hover { background: #E2E8F0; }

/* 3 Cards Grid */
.wei-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 32px;
}
@media (max-width: 860px) {
  .wei-cards-grid { grid-template-columns: 1fr; }
}

.wei-role-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 36px 24px 30px;
  text-align: center;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
  transition: transform 0.2s, box-shadow 0.2s;
}
.wei-role-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
}
.wei-card-icon-wrap {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: #EFF6FF;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 18px;
}
.wei-card-title {
  font-size: 20px;
  font-weight: 700;
  color: #0F172A;
  margin: 0 0 8px;
}
.wei-card-desc {
  font-size: 13px;
  color: #64748B;
  min-height: 38px;
  margin: 0 0 24px;
}
.btn-card-login {
  display: block;
  width: 100%;
  max-width: 180px;
  margin: 0 auto;
  background: #1976D2;
  color: #FFFFFF !important;
  font-size: 14px;
  font-weight: 600;
  padding: 10px 0;
  border-radius: 6px;
  border: none;
  text-align: center;
  text-decoration: none !important;
  transition: background 0.2s;
}
.btn-card-login:hover {
  background: #1565C0;
}
.btn-card-login.disabled {
  background: #E2E8F0;
  color: #94A3B8 !important;
  cursor: not-allowed;
}

/* 4-Step Process Strip */
.wei-process-strip {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 24px 32px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
@media (max-width: 860px) {
  .wei-process-strip {
    flex-direction: column;
    align-items: flex-start;
  }
  .wei-step-connector { display: none; }
}

.wei-step-item {
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 1;
}
.wei-step-badge {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  color: #FFFFFF;
  font-size: 15px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.badge-blue   { background: #1976D2; }
.badge-green  { background: #16A34A; }
.badge-orange { background: #F59E0B; }
.badge-purple { background: #8B5CF6; }

.wei-step-content {
  text-align: left;
}
.wei-step-title {
  font-size: 14px;
  font-weight: 700;
  color: #0F172A;
  margin: 0 0 2px;
}
.wei-step-desc {
  font-size: 12px;
  color: #64748B;
  margin: 0;
  line-height: 1.3;
}
.wei-step-connector {
  width: 28px;
  height: 2px;
  background: #E2E8F0;
  flex-shrink: 0;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userName = gs.getUserDisplayName() || 'User';

  data.hasStaff = gs.hasRole('x_1956908_wareho_0.staff') || gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
  data.hasTech = gs.hasRole('x_1956908_wareho_0.technician') || gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
  data.hasSupervisor = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
})();
